CONSUME = 'def consume_inventory_for_order(order):\n    """Deduct recipe components once at delivery. Drinks are deducted from fridge stock."""\n    from .models import ProductCostProfile, InventoryMovement, Ingredient\n\n    if order.status != Order.STATUS_DELIVERED:\n        return {\'created\': 0, \'skipped\': 0, \'fridge_alerts\': []}\n\n    order_items = order.items.select_related(\'menu_item\').all()\n    profiles = {\n        profile.menu_item_id: profile\n        for profile in ProductCostProfile.objects.prefetch_related(\'components__ingredient\').filter(\n            menu_item_id__in=[row.menu_item_id for row in order_items if row.menu_item_id]\n        )\n    }\n    created = 0\n    skipped = 0\n    fridge_alerts = []\n    for order_item in order_items:\n        profile = profiles.get(order_item.menu_item_id)\n        if not profile:\n            continue\n        for component in profile.components.all():\n            quantity = _inventory_decimal(component.quantity) * _inventory_decimal(order_item.quantity)\n            if quantity <= 0:\n                continue\n            movement, was_created = _inventory_apply_movement(\n                ingredient_id=component.ingredient_id,\n                movement_type=InventoryMovement.TYPE_SALE,\n                quantity_delta=-quantity,\n                unit_cost_snapshot=component.ingredient.unit_cost,\n                total_cost=quantity * _inventory_decimal(component.ingredient.unit_cost),\n                order_item=order_item,\n                reference=f\'Pedido {order.order_code}\',\n                notes=f\'Consumo automático: {order_item.name_snapshot}\',\n                occurred_at=order.updated_at or timezone.now(),\n                username=\'system\',\n            )\n            if was_created:\n                created += 1\n                # A beverage is one Ingredient with two locations. A delivered sale\n                # always consumes from the fridge; global stock is already reduced above.\n                ingredient = Ingredient.objects.select_for_update().get(id=component.ingredient_id)\n                if ingredient.is_beverage:\n                    before = _inventory_decimal(ingredient.fridge_stock)\n                    fridge_after = max(Decimal(\'0.00\'), before - quantity)\n                    ingredient.fridge_stock = fridge_after\n                    ingredient.save(update_fields=[\'fridge_stock\', \'updated_at\'])\n                    if fridge_after <= _inventory_decimal(ingredient.fridge_alert_level):\n                        fridge_alerts.append({\n                            \'ingredient_id\': ingredient.id,\n                            \'name\': ingredient.name,\n                            \'fridge_stock\': float(fridge_after),\n                            \'level\': \'fridge_low\',\n                        })\n                    if _inventory_decimal(ingredient.stock_quantity) < _inventory_decimal(ingredient.total_alert_level):\n                        fridge_alerts.append({\n                            \'ingredient_id\': ingredient.id,\n                            \'name\': ingredient.name,\n                            \'stock_quantity\': float(ingredient.stock_quantity),\n                            \'level\': \'total_low\',\n                        })\n            else:\n                skipped += 1\n    return {\'created\': created, \'skipped\': skipped, \'fridge_alerts\': fridge_alerts}'
OVERVIEW = "def admin_inventory_real_overview(request):\n    from datetime import timedelta\n    from .models import Ingredient, InventoryMovement, RecipeIngredient\n\n    today = timezone.localdate()\n    days = max(1, min(90, int(request.query_params.get('days', 14) or 14)))\n    start = today - timedelta(days=days - 1)\n\n    sales = (\n        Order.objects.filter(created_at__date__gte=start, created_at__date__lte=today)\n        .exclude(status=Order.STATUS_CANCELLED)\n        .filter(status=Order.STATUS_DELIVERED)\n        .values('items__menu_item_id')\n        .annotate(units=Sum('items__quantity'))\n    )\n    units_by_item = {row['items__menu_item_id']: _inventory_decimal(row['units']) for row in sales if row.get('items__menu_item_id')}\n    daily_usage = {}\n    for component in RecipeIngredient.objects.select_related('profile', 'ingredient').all():\n        sold = units_by_item.get(component.profile.menu_item_id, Decimal('0.00'))\n        if sold:\n            daily_usage[component.ingredient_id] = daily_usage.get(component.ingredient_id, Decimal('0.00')) + (\n                _inventory_decimal(component.quantity) * sold / Decimal(days)\n            )\n\n    ingredients, suggestions, beverages, beverage_alerts = [], [], [], []\n    for ingredient in Ingredient.objects.filter(is_active=True).order_by('name'):\n        stock = _inventory_decimal(ingredient.stock_quantity)\n        average = daily_usage.get(ingredient.id, Decimal('0.00'))\n        reorder = _inventory_decimal(ingredient.reorder_level)\n        days_left = (stock / average) if average > 0 else None\n        target = max(reorder, average * Decimal('7'))\n        suggested_quantity = max(Decimal('0.00'), target - stock)\n        status_name = 'ok'\n        if days_left is not None and days_left <= Decimal('1.5'):\n            status_name = 'urgent'\n        elif stock <= reorder:\n            status_name = 'low'\n\n        fridge_stock = min(max(Decimal('0.00'), _inventory_decimal(ingredient.fridge_stock)), stock)\n        outside_stock = max(Decimal('0.00'), stock - fridge_stock)\n        row = {\n            'id': ingredient.id,\n            'name': ingredient.name,\n            'unit': ingredient.unit,\n            'stock_quantity': float(stock),\n            'unit_cost': float(ingredient.unit_cost or 0),\n            'reorder_level': float(reorder),\n            'supplier_name': ingredient.supplier_name or '',\n            'is_beverage': bool(ingredient.is_beverage),\n            'fridge_stock': float(fridge_stock),\n            'outside_stock': float(outside_stock),\n            'fridge_alert_level': float(ingredient.fridge_alert_level),\n            'total_alert_level': float(ingredient.total_alert_level),\n            'average_daily_usage': float(average.quantize(Decimal('0.001'))),\n            'estimated_days_left': float(days_left.quantize(Decimal('0.1'))) if days_left is not None else None,\n            'suggested_purchase_quantity': float(suggested_quantity.quantize(Decimal('0.001'))),\n            'status': status_name,\n        }\n        ingredients.append(row)\n        if suggested_quantity > 0:\n            suggestions.append(row)\n        if ingredient.is_beverage:\n            beverages.append(row)\n            if fridge_stock <= _inventory_decimal(ingredient.fridge_alert_level):\n                beverage_alerts.append({**row, 'alert_type': 'fridge_low'})\n            if stock < _inventory_decimal(ingredient.total_alert_level):\n                beverage_alerts.append({**row, 'alert_type': 'total_low'})\n\n    movements = InventoryMovement.objects.select_related('ingredient').order_by('-occurred_at', '-id')[:80]\n    return Response({\n        'days_window': days,\n        'ingredients': ingredients,\n        'suggested_purchase_list': suggestions,\n        'beverages': beverages,\n        'beverage_alerts': beverage_alerts,\n        'recent_movements': [_inventory_movement_payload(row) for row in movements],\n    })"
ADJUSTMENT = 'def admin_inventory_adjustment(request):\n    """Normal physical adjustment plus beverage configuration and fridge transfers."""\n    from .models import Ingredient, InventoryMovement\n\n    data = request.data or {}\n    try:\n        ingredient = Ingredient.objects.select_for_update().get(id=int(data.get(\'ingredient_id\')))\n        action = str(data.get(\'action\') or \'\').strip()\n\n        if action == \'configure_beverage\':\n            is_beverage = bool(data.get(\'is_beverage\', True))\n            fridge_stock = _inventory_decimal(data.get(\'fridge_stock\') if data.get(\'fridge_stock\') not in (None, \'\') else ingredient.fridge_stock)\n            fridge_level = _inventory_decimal(data.get(\'fridge_alert_level\') if data.get(\'fridge_alert_level\') not in (None, \'\') else \'2\')\n            total_level = _inventory_decimal(data.get(\'total_alert_level\') if data.get(\'total_alert_level\') not in (None, \'\') else \'8\')\n            if fridge_stock < 0 or fridge_stock > _inventory_decimal(ingredient.stock_quantity):\n                raise ValueError(\'El stock de nevera debe estar entre 0 y el stock total.\')\n            if fridge_level < 0 or total_level < 0:\n                raise ValueError(\'Los niveles de alerta no pueden ser negativos.\')\n            ingredient.is_beverage = is_beverage\n            ingredient.fridge_stock = fridge_stock if is_beverage else Decimal(\'0.00\')\n            ingredient.fridge_alert_level = fridge_level\n            ingredient.total_alert_level = total_level\n            ingredient.save(update_fields=[\'is_beverage\', \'fridge_stock\', \'fridge_alert_level\', \'total_alert_level\', \'updated_at\'])\n            return Response({\'success\': True, \'action\': action, \'ingredient_id\': ingredient.id})\n\n        if action == \'transfer_to_fridge\':\n            if not ingredient.is_beverage:\n                raise ValueError(\'Primero configura este ingrediente como bebida.\')\n            quantity = _inventory_decimal(data.get(\'quantity\'))\n            if quantity <= 0:\n                raise ValueError(\'La cantidad a pasar a la nevera debe ser mayor que cero.\')\n            outside = _inventory_decimal(ingredient.stock_quantity) - _inventory_decimal(ingredient.fridge_stock)\n            if quantity > outside:\n                raise ValueError(\'No hay suficientes bebidas fuera de la nevera para esta transferencia.\')\n            _inventory_apply_movement(\n                ingredient_id=ingredient.id,\n                movement_type=InventoryMovement.TYPE_FRIDGE_TRANSFER,\n                quantity_delta=Decimal(\'0.00\'),\n                unit_cost_snapshot=ingredient.unit_cost,\n                total_cost=Decimal(\'0.00\'),\n                reference=\'Traslado al frigorífico\',\n                notes=str(data.get(\'notes\') or \'\').strip(),\n                username=request.admin_user.get_username(),\n            )\n            ingredient.refresh_from_db()\n            ingredient.fridge_stock = _inventory_decimal(ingredient.fridge_stock) + quantity\n            ingredient.save(update_fields=[\'fridge_stock\', \'updated_at\'])\n            return Response({\'success\': True, \'action\': action, \'ingredient_id\': ingredient.id, \'fridge_stock\': float(ingredient.fridge_stock)})\n\n        delta = _inventory_decimal(data.get(\'quantity_delta\'))\n        if delta == 0:\n            raise ValueError(\'El ajuste no puede ser cero.\')\n        movement, _ = _inventory_apply_movement(\n            ingredient_id=ingredient.id,\n            movement_type=InventoryMovement.TYPE_ADJUSTMENT,\n            quantity_delta=delta,\n            unit_cost_snapshot=ingredient.unit_cost,\n            total_cost=abs(delta) * _inventory_decimal(ingredient.unit_cost),\n            reference=\'Ajuste manual\',\n            notes=str(data.get(\'notes\') or \'\').strip(),\n            username=request.admin_user.get_username(),\n        )\n        ingredient.refresh_from_db()\n        if ingredient.is_beverage and _inventory_decimal(ingredient.fridge_stock) > _inventory_decimal(ingredient.stock_quantity):\n            ingredient.fridge_stock = _inventory_decimal(ingredient.stock_quantity)\n            ingredient.save(update_fields=[\'fridge_stock\', \'updated_at\'])\n    except (ValueError, TypeError, Ingredient.DoesNotExist) as exc:\n        return Response({\'detail\': str(exc)}, status=status.HTTP_400_BAD_REQUEST)\n    return Response({\'success\': True, \'movement\': _inventory_movement_payload(movement)}, status=status.HTTP_201_CREATED)'
PANEL = 'function RealInventoryPanel({ expenseCategories = [] }) {\n  const language = useGlobalAdminLanguage(); const setLanguage = changeAdminUiLanguage;\n  const [data, setData] = useState({ ingredients: [], suggested_purchase_list: [], recent_movements: [] });\n  const [loading, setLoading] = useState(false);\n  const [mode, setMode] = useState(\'purchase\');\n  const [form, setForm] = useState({ ingredient_id: \'\', quantity: \'\', counted_quantity: \'\', unit_cost: \'\', iva_percent: \'10\', supplier_name: \'\', invoice_number: \'\', paid_by: \'bbva\', payment_method: \'bbva\', notes: \'\' });\n  const [ingredientForm, setIngredientForm] = useState({ name:\'\', unit:\'kg\', unit_cost:\'\', stock_quantity:\'0\', reorder_level:\'\', supplier_name:\'\' });\n  const [drinkForm, setDrinkForm] = useState({ ingredient_id:\'\', fridge_stock:\'\', fridge_alert_level:\'2\', total_alert_level:\'8\', transfer_quantity:\'\', notes:\'\' });\n  const tr = {\n    es: { title:\'Compras e Inventario Real\', sub:\'Crea materias primas, registra compras, mermas y corrige el stock contado por el administrador.\', refresh:\'Actualizar\', addIngredient:\'Añadir materia prima\', purchase:\'Registrar compra\', waste:\'Registrar merma\', adjust:\'Corregir stock\', stock:\'Stock real\', suggested:\'Lista de compra sugerida (7 días)\', movements:\'Movimientos recientes\', ingredient:\'Ingrediente\', ingredientName:\'Nombre de la materia prima\', unit:\'Unidad\', unitCost:\'Coste por unidad (€)\', initialStock:\'Stock inicial\', minimumStock:\'Stock mínimo / alerta\', quantity:\'Cantidad\', counted:\'Stock real contado\', current:\'Stock actual del sistema\', difference:\'Diferencia que se registrará\', amount:\'Importe total (€)\', subtotal:\'Base sin IVA\', ivaRate:\'IVA (%)\', ivaAmount:\'Importe IVA\', totalWithIva:\'Total con IVA\', ivaHint:\'El total se calcula automáticamente a partir de cantidad, coste unitario e IVA.\', supplier:\'Proveedor\', invoice:\'Factura\', notes:\'Motivo / notas\', save:\'Guardar\', create:\'Crear materia prima\', days:\'Días\', use:\'Consumo/día\', noData:\'No hay ingredientes configurados.\', purchaseDone:\'Compra registrada y gasto añadido a Contabilidad.\', wasteDone:\'Merma registrada.\', adjustmentDone:\'Stock corregido y movimiento de ajuste guardado.\', ingredientDone:\'Materia prima creada. Ya puedes registrar su compra.\', type:\'Tipo\', delta:\'Cambio\', stockNow:\'Stock actual\', danger:\'Urgente\', low:\'Bajo\', ok:\'Correcto\', needName:\'Escribe el nombre de la materia prima.\', selectIngredient:\'Selecciona una materia prima.\', noChange:\'El stock contado es igual al stock actual; no hay nada que corregir.\', adjustmentHelp:\'Usa esta opción después de contar físicamente el almacén. No registra un gasto ni una compra.\' },\n    fa: { title:\'خرید و انبار واقعی\', sub:\'ماده اولیه بسازید، خرید و ضایعات را ثبت کنید و موجودی شمارش\u200cشده را توسط مدیر اصلاح کنید.\', refresh:\'به\u200cروزرسانی\', addIngredient:\'افزودن ماده اولیه\', purchase:\'ثبت خرید\', waste:\'ثبت ضایعات\', adjust:\'اصلاح موجودی\', stock:\'موجودی واقعی\', suggested:\'لیست خرید پیشنهادی (۷ روز)\', movements:\'گردش\u200cهای اخیر\', ingredient:\'ماده اولیه\', ingredientName:\'نام ماده اولیه\', unit:\'واحد\', unitCost:\'هزینه هر واحد (€)\', initialStock:\'موجودی اولیه\', minimumStock:\'حداقل موجودی / هشدار\', quantity:\'مقدار\', counted:\'موجودی واقعی شمارش\u200cشده\', current:\'موجودی فعلی سیستم\', difference:\'اختلافی که ثبت می\u200cشود\', amount:\'مبلغ کل (€)\', subtotal:\'مبلغ بدون IVA\', ivaRate:\'درصد IVA\', ivaAmount:\'مبلغ IVA\', totalWithIva:\'مبلغ نهایی با IVA\', ivaHint:\'مبلغ نهایی با مقدار، هزینه واحد و IVA به\u200cصورت خودکار محاسبه می\u200cشود.\', supplier:\'تأمین\u200cکننده\', invoice:\'شماره فاکتور\', notes:\'علت / توضیحات\', save:\'ذخیره\', create:\'ساخت ماده اولیه\', days:\'روز\', use:\'مصرف/روز\', noData:\'ماده اولیه\u200cای تعریف نشده است.\', purchaseDone:\'خرید ثبت و هزینه آن به حسابداری اضافه شد.\', wasteDone:\'ضایعات ثبت شد.\', adjustmentDone:\'موجودی اصلاح و گردش اصلاح ثبت شد.\', ingredientDone:\'ماده اولیه ساخته شد؛ اکنون می\u200cتوانید خرید آن را ثبت کنید.\', type:\'نوع\', delta:\'تغییر\', stockNow:\'موجودی فعلی\', danger:\'فوری\', low:\'کم\', ok:\'مناسب\', needName:\'نام ماده اولیه را وارد کنید.\', selectIngredient:\'یک ماده اولیه انتخاب کنید.\', noChange:\'موجودی شمارش\u200cشده با موجودی فعلی برابر است و نیازی به اصلاح نیست.\', adjustmentHelp:\'پس از شمارش واقعی انبار از این گزینه استفاده کنید. این عملیات خرید یا هزینه مالی ثبت نمی\u200cکند.\' },\n    ar: { title:\'المشتريات والمخزون الفعلي\', sub:\'أنشئ المواد الأولية وسجل المشتريات والهدر وصحح المخزون الذي عده المدير.\', refresh:\'تحديث\', addIngredient:\'إضافة مادة أولية\', purchase:\'تسجيل شراء\', waste:\'تسجيل هدر\', adjust:\'تصحيح المخزون\', stock:\'المخزون الفعلي\', suggested:\'قائمة شراء مقترحة (7 أيام)\', movements:\'آخر الحركات\', ingredient:\'المادة\', ingredientName:\'اسم المادة الأولية\', unit:\'الوحدة\', unitCost:\'تكلفة الوحدة (€)\', initialStock:\'المخزون الافتتاحي\', minimumStock:\'الحد الأدنى / تنبيه\', quantity:\'الكمية\', counted:\'المخزون الفعلي المعدود\', current:\'مخزون النظام الحالي\', difference:\'الفرق الذي سيتم تسجيله\', amount:\'إجمالي المبلغ (€)\', subtotal:\'المبلغ بدون IVA\', ivaRate:\'نسبة IVA\', ivaAmount:\'مبلغ IVA\', totalWithIva:\'الإجمالي مع IVA\', ivaHint:\'يحسب الإجمالي تلقائياً من الكمية وتكلفة الوحدة وIVA.\', supplier:\'المورد\', invoice:\'رقم الفاتورة\', notes:\'السبب / ملاحظات\', save:\'حفظ\', create:\'إنشاء المادة الأولية\', days:\'الأيام\', use:\'الاستهلاك/يوم\', noData:\'لا توجد مواد أولية مضافة.\', purchaseDone:\'تم تسجيل الشراء وإضافة المصروف للمحاسبة.\', wasteDone:\'تم تسجيل الهدر.\', adjustmentDone:\'تم تصحيح المخزون وحفظ حركة التصحيح.\', ingredientDone:\'تم إنشاء المادة الأولية ويمكنك الآن تسجيل شرائها.\', type:\'النوع\', delta:\'التغيير\', stockNow:\'المخزون الحالي\', danger:\'عاجل\', low:\'منخفض\', ok:\'جيد\', needName:\'اكتب اسم المادة الأولية.\', selectIngredient:\'اختر مادة أولية.\', noChange:\'المخزون المعدود يساوي المخزون الحالي ولا يوجد شيء لتصحيحه.\', adjustmentHelp:\'استخدم هذا الخيار بعد العد الفعلي للمخزون. لا يسجل شراءً أو مصروفاً مالياً.\' },\n  }[language];\n\n  const load = async () => {\n    try { setLoading(true); const res = await axios.get(`${API_BASE}/admin/inventory/overview/?days=14`); setData(res.data || {}); }\n    catch (err) { window.alert(err?.response?.data?.detail || \'No se pudo cargar el inventario.\'); }\n    finally { setLoading(false); }\n  };\n  useEffect(() => { load(); }, []);\n\n  const selected = (data.ingredients || []).find(x => String(x.id) === String(form.ingredient_id));\n  const purchaseQuantity = Number(form.quantity || 0);\n  const purchaseUnitCost = Number(form.unit_cost || 0);\n  const ivaPercent = Math.max(0, Math.min(100, Number(form.iva_percent || 0)));\n  const purchaseSubtotal = purchaseQuantity * purchaseUnitCost;\n  const purchaseIvaAmount = purchaseSubtotal * ivaPercent / 100;\n  const purchaseTotal = purchaseSubtotal + purchaseIvaAmount;\n  const adjustmentDelta = selected && form.counted_quantity !== \'\' ? Number(form.counted_quantity) - Number(selected.stock_quantity || 0) : null;\n\n  const submitMovement = async e => {\n    e.preventDefault();\n    if (!form.ingredient_id) { window.alert(tr.selectIngredient); return; }\n    let endpoint = \'waste\';\n    let payload = { ingredient_id:form.ingredient_id, quantity:form.quantity, notes:form.notes };\n    if (mode === \'purchase\') {\n      endpoint = \'purchase\';\n      payload = { ...form, unit_cost: purchaseUnitCost.toFixed(4), iva_percent: ivaPercent.toFixed(2) };\n    } else if (mode === \'adjust\') {\n      endpoint = \'adjustment\';\n      if (adjustmentDelta === null || Number.isNaN(adjustmentDelta) || Math.abs(adjustmentDelta) < 0.000001) { window.alert(tr.noChange); return; }\n      payload = { ingredient_id:form.ingredient_id, quantity_delta:adjustmentDelta.toFixed(3), notes:form.notes };\n    }\n    try {\n      await axios.post(`${API_BASE}/admin/inventory/${endpoint}/`, payload);\n      window.alert(mode === \'purchase\' ? tr.purchaseDone : mode === \'waste\' ? tr.wasteDone : tr.adjustmentDone);\n      setForm(current => ({...current, quantity:\'\', counted_quantity:\'\', invoice_number:\'\', notes:\'\'}));\n      await load();\n    } catch (err) { window.alert(err?.response?.data?.detail || \'No se pudo guardar el movimiento.\'); }\n  };\n\n  const createIngredient = async e => {\n    e.preventDefault();\n    if (!ingredientForm.name.trim()) { window.alert(tr.needName); return; }\n    try {\n      const res = await axios.post(`${API_BASE}/admin/profitability/ingredients/`, {\n        ...ingredientForm, unit_cost:ingredientForm.unit_cost || 0, stock_quantity:ingredientForm.stock_quantity || 0,\n        reorder_level:ingredientForm.reorder_level || 0, is_active:true,\n      });\n      window.alert(tr.ingredientDone);\n      setForm(current => ({ ...current, ingredient_id:String(res.data?.id || \'\') }));\n      setIngredientForm({ name:\'\', unit:\'kg\', unit_cost:\'\', stock_quantity:\'0\', reorder_level:\'\', supplier_name:\'\' });\n      setMode(\'purchase\'); await load();\n    } catch (err) { window.alert(err?.response?.data?.detail || \'No se pudo crear la materia prima.\'); }\n  };\n\n  const drinks = data.beverages || [];\n  const drinkSelected = drinks.find(x => String(x.id) === String(drinkForm.ingredient_id)) || (data.ingredients || []).find(x => String(x.id) === String(drinkForm.ingredient_id));\n\n  const configureDrink = async e => {\n    e.preventDefault();\n    if (!drinkForm.ingredient_id) return window.alert(language === \'fa\' ? \'نوشیدنی را انتخاب کنید.\' : \'Selecciona una bebida.\');\n    try {\n      await axios.post(`${API_BASE}/admin/inventory/adjustment/`, {\n        action:\'configure_beverage\', ingredient_id:drinkForm.ingredient_id, is_beverage:true,\n        fridge_stock:drinkForm.fridge_stock || 0, fridge_alert_level:drinkForm.fridge_alert_level || 2,\n        total_alert_level:drinkForm.total_alert_level || 8, notes:drinkForm.notes,\n      });\n      window.alert(language === \'fa\' ? \'نوشیدنی و هشدارهای آن ذخیره شد.\' : \'Bebida y alertas guardadas.\');\n      await load();\n    } catch (err) { window.alert(err?.response?.data?.detail || \'No se pudo configurar la bebida.\'); }\n  };\n\n  const transferDrink = async e => {\n    e.preventDefault();\n    if (!drinkForm.ingredient_id || Number(drinkForm.transfer_quantity || 0) <= 0) return window.alert(language === \'fa\' ? \'نوشیدنی و تعداد انتقال را وارد کنید.\' : \'Selecciona bebida e indica la cantidad.\');\n    try {\n      await axios.post(`${API_BASE}/admin/inventory/adjustment/`, {\n        action:\'transfer_to_fridge\', ingredient_id:drinkForm.ingredient_id,\n        quantity:drinkForm.transfer_quantity, notes:drinkForm.notes,\n      });\n      window.alert(language === \'fa\' ? \'نوشیدنی به یخچال منتقل شد.\' : \'Bebida trasladada a la nevera.\');\n      setDrinkForm(current => ({...current, transfer_quantity:\'\', notes:\'\'}));\n      await load();\n    } catch (err) { window.alert(err?.response?.data?.detail || \'No se pudo trasladar la bebida.\'); }\n  };\n\n  return <section className={`real-inventory-page lang-${language}`} dir={language === \'es\' ? \'ltr\' : \'rtl\'}>\n    <section className="admin-card real-inventory-head"><div><span className="admin-kicker">GESTIÓN DIARIA</span><h2>{tr.title}</h2><p>{tr.sub}</p></div><div className="real-inventory-actions"><button className="smart-primary" onClick={load} disabled={loading}>{loading?\'...\':tr.refresh}</button></div></section>\n    <section className="real-inventory-grid">\n      <article className="admin-card inventory-action-card">\n        <div className="real-mode-switch"><button className={mode===\'add\'?\'active\':\'\'} onClick={()=>setMode(\'add\')}>{tr.addIngredient}</button><button className={mode===\'purchase\'?\'active\':\'\'} onClick={()=>setMode(\'purchase\')}>{tr.purchase}</button><button className={mode===\'waste\'?\'active\':\'\'} onClick={()=>setMode(\'waste\')}>{tr.waste}</button><button className={mode===\'adjust\'?\'active\':\'\'} onClick={()=>setMode(\'adjust\')}>{tr.adjust}</button></div>\n\n        {mode === \'add\' ? <form className="smart-recurring-form" onSubmit={createIngredient}>\n          <input required placeholder={tr.ingredientName} value={ingredientForm.name} onChange={e=>setIngredientForm({...ingredientForm,name:e.target.value})}/>\n          <select value={ingredientForm.unit} onChange={e=>setIngredientForm({...ingredientForm,unit:e.target.value})}><option value="kg">kg</option><option value="g">g</option><option value="l">l</option><option value="ml">ml</option><option value="unit">unidad</option><option value="pack">pack</option></select>\n          <input type="number" min="0" step="0.0001" placeholder={tr.unitCost} value={ingredientForm.unit_cost} onChange={e=>setIngredientForm({...ingredientForm,unit_cost:e.target.value})}/>\n          <input type="number" min="0" step="0.001" placeholder={`${tr.initialStock} (${ingredientForm.unit})`} value={ingredientForm.stock_quantity} onChange={e=>setIngredientForm({...ingredientForm,stock_quantity:e.target.value})}/>\n          <input type="number" min="0" step="0.001" placeholder={`${tr.minimumStock} (${ingredientForm.unit})`} value={ingredientForm.reorder_level} onChange={e=>setIngredientForm({...ingredientForm,reorder_level:e.target.value})}/>\n          <input placeholder={tr.supplier} value={ingredientForm.supplier_name} onChange={e=>setIngredientForm({...ingredientForm,supplier_name:e.target.value})}/><button className="pay">{tr.create}</button>\n        </form> : <form className="smart-recurring-form" onSubmit={submitMovement}>\n          <select required value={form.ingredient_id} onChange={e=>{ const id=e.target.value; const item=(data.ingredients||[]).find(x=>String(x.id)===String(id)); setForm({...form,ingredient_id:id, counted_quantity:\'\', unit_cost:item ? String(item.unit_cost || \'\') : form.unit_cost}); }}><option value="">{tr.ingredient}</option>{(data.ingredients||[]).map(i=><option key={i.id} value={i.id}>{i.name} · {i.stock_quantity} {i.unit}</option>)}</select>\n          {mode===\'adjust\' ? <div className="inventory-adjust-box">\n            <p>{tr.adjustmentHelp}</p>\n            {selected && <div className="inventory-current-stock"><b>{tr.current}:</b> {selected.stock_quantity} {selected.unit}</div>}\n            <input required type="number" min="0" step="0.001" placeholder={`${tr.counted}${selected ? ` (${selected.unit})` : \'\'}`} value={form.counted_quantity} onChange={e=>setForm({...form,counted_quantity:e.target.value})}/>\n            {adjustmentDelta !== null && !Number.isNaN(adjustmentDelta) && <div className={`inventory-adjust-delta ${adjustmentDelta > 0 ? \'positive\' : adjustmentDelta < 0 ? \'negative\' : \'\'}`}><b>{tr.difference}:</b> {adjustmentDelta > 0 ? \'+\' : \'\'}{adjustmentDelta.toFixed(3)} {selected?.unit || \'\'}</div>}\n          </div> : <>\n            <input required type="number" min="0.001" step="0.001" placeholder={`${tr.quantity}${selected ? ` (${selected.unit})` : \'\'}`} value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/>\n            {mode===\'purchase\' && <><input required type="number" min="0" step="0.0001" placeholder={tr.unitCost} value={form.unit_cost} onChange={e=>setForm({...form,unit_cost:e.target.value})}/><input type="number" min="0" max="100" step="0.01" placeholder={tr.ivaRate} value={form.iva_percent} onChange={e=>setForm({...form,iva_percent:e.target.value})}/><div className="purchase-tax-summary"><p>{tr.ivaHint}</p><div><span>{tr.subtotal}</span><b>{money(purchaseSubtotal)}</b></div><div><span>{tr.ivaAmount} ({ivaPercent.toFixed(2)}%)</span><b>{money(purchaseIvaAmount)}</b></div><div className="purchase-tax-total"><span>{tr.totalWithIva}</span><b>{money(purchaseTotal)}</b></div></div><input placeholder={tr.supplier} value={form.supplier_name} onChange={e=>setForm({...form,supplier_name:e.target.value})}/><input placeholder={tr.invoice} value={form.invoice_number} onChange={e=>setForm({...form,invoice_number:e.target.value})}/><select value={form.paid_by} onChange={e=>setForm({...form,paid_by:e.target.value})}><option value="bbva">BBVA</option><option value="saeid">Saeid</option><option value="ahmed">Ahmed</option></select></>}\n          </>}\n          <textarea placeholder={tr.notes} value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/><button className="pay">{mode===\'adjust\' ? tr.adjust : tr.save}</button>\n        </form>}\n      </article>\n      <article className="admin-card"><h2>{tr.suggested}</h2><div className="smart-stock-list">{(data.suggested_purchase_list||[]).length ? data.suggested_purchase_list.map(i=><div className={`smart-stock-row ${i.status}`} key={i.id}><b>{i.name}</b><span>+{i.suggested_purchase_quantity} {i.unit}</span><small>{tr.stockNow}: {i.stock_quantity} · {tr.days}: {i.estimated_days_left ?? \'—\'}</small></div>) : <p className="muted">✓ {tr.ok}</p>}</div></article>\n    </section>\n    <section className="admin-card"><h2>{tr.stock}</h2><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>{tr.ingredient}</th><th>{tr.stockNow}</th><th>{tr.use}</th><th>{tr.days}</th><th>€/u</th><th>Estado</th></tr></thead><tbody>{(data.ingredients||[]).map(i=><tr key={i.id}><td>{i.name}</td><td>{i.stock_quantity} {i.unit}</td><td>{i.average_daily_usage}</td><td>{i.estimated_days_left ?? \'—\'}</td><td>{money(i.unit_cost)}</td><td><span className={`inventory-status ${i.status}`}>{i.status===\'urgent\'?tr.danger:i.status===\'low\'?tr.low:tr.ok}</span></td></tr>)}{!(data.ingredients||[]).length&&<tr><td colSpan="6" className="muted">{tr.noData}</td></tr>}</tbody></table></div></section>\n    <section className="admin-card beverage-inventory-panel">\n      <div className="beverage-panel-head"><div><span className="admin-kicker">BEBIDAS</span><h2>{language === \'fa\' ? \'مدیریت نوشیدنی و یخچال\' : language === \'ar\' ? \'إدارة المشروبات والثلاجة\' : \'Gestión de bebidas y nevera\'}</h2><p>{language === \'fa\' ? \'فروش سفارش تحویل\u200cشده، ابتدا از یخچال کم می\u200cشود. موجودی کل = یخچال + بیرون یخچال.\' : \'Cada venta entregada descuenta la bebida de la nevera. Stock total = nevera + fuera de nevera.\'}</p></div></div>\n      {(data.beverage_alerts || []).length > 0 && <div className="beverage-alerts">{data.beverage_alerts.map((item,index)=><div className={`beverage-alert ${item.alert_type}`} key={`${item.id}-${item.alert_type}-${index}`}>{item.alert_type === \'fridge_low\' ? <>⚠ {item.name}: {language === \'fa\' ? \'موجودی یخچال\' : \'Stock nevera\'} {item.fridge_stock} {item.unit} {language === \'fa\' ? \'است؛ یخچال را شارژ کنید.\' : \' — recarga la nevera.\'}</> : <>⚠ {item.name}: {language === \'fa\' ? \'موجودی کل فقط\' : \'Stock total\'} {item.stock_quantity} {item.unit} {language === \'fa\' ? \'است؛ خرید جدید لازم است.\' : \' — hace falta comprar.\'}</>}</div>)}</div>}\n      <div className="beverage-grid">\n        <form className="smart-recurring-form beverage-form" onSubmit={configureDrink}>\n          <h3>{language === \'fa\' ? \'تعریف یا تنظیم نوشیدنی\' : \'Configurar bebida\'}</h3>\n          <select required value={drinkForm.ingredient_id} onChange={e=>{const id=e.target.value; const item=(data.ingredients||[]).find(x=>String(x.id)===String(id)); setDrinkForm({...drinkForm, ingredient_id:id, fridge_stock:item ? String(item.fridge_stock || 0) : \'\', fridge_alert_level:item ? String(item.fridge_alert_level ?? 2) : \'2\', total_alert_level:item ? String(item.total_alert_level ?? 8) : \'8\'});}}><option value="">{language === \'fa\' ? \'انتخاب ماده اولیه نوشیدنی\' : \'Seleccionar ingrediente de bebida\'}</option>{(data.ingredients||[]).filter(i=>i.unit===\'unit\' || i.is_beverage).map(i=><option key={i.id} value={i.id}>{i.name} · {i.stock_quantity} {i.unit}</option>)}</select>\n          <input required type="number" min="0" step="1" placeholder={language === \'fa\' ? \'تعداد داخل یخچال\' : \'Unidades dentro de nevera\'} value={drinkForm.fridge_stock} onChange={e=>setDrinkForm({...drinkForm,fridge_stock:e.target.value})}/>\n          <input type="number" min="0" step="1" placeholder={language === \'fa\' ? \'هشدار یخچال (پیش\u200cفرض ۲)\' : \'Alerta nevera (por defecto 2)\'} value={drinkForm.fridge_alert_level} onChange={e=>setDrinkForm({...drinkForm,fridge_alert_level:e.target.value})}/>\n          <input type="number" min="0" step="1" placeholder={language === \'fa\' ? \'هشدار کل (پیش\u200cفرض ۸)\' : \'Alerta total (por defecto 8)\'} value={drinkForm.total_alert_level} onChange={e=>setDrinkForm({...drinkForm,total_alert_level:e.target.value})}/>\n          <button className="pay">{language === \'fa\' ? \'ذخیره تنظیم نوشیدنی\' : \'Guardar bebida\'}</button>\n        </form>\n        <form className="smart-recurring-form beverage-form" onSubmit={transferDrink}>\n          <h3>{language === \'fa\' ? \'انتقال از بیرون به یخچال\' : \'Pasar de fuera a nevera\'}</h3>\n          <select required value={drinkForm.ingredient_id} onChange={e=>{const id=e.target.value; const item=drinks.find(x=>String(x.id)===String(id)); setDrinkForm({...drinkForm, ingredient_id:id, fridge_stock:item ? String(item.fridge_stock || 0) : drinkForm.fridge_stock, fridge_alert_level:item ? String(item.fridge_alert_level ?? 2) : drinkForm.fridge_alert_level, total_alert_level:item ? String(item.total_alert_level ?? 8) : drinkForm.total_alert_level});}}><option value="">{language === \'fa\' ? \'انتخاب نوشیدنی\' : \'Seleccionar bebida\'}</option>{drinks.map(i=><option key={i.id} value={i.id}>{i.name} · {i.fridge_stock} en nevera / {i.outside_stock} fuera</option>)}</select>\n          {drinkSelected && <div className="beverage-location-summary"><span>{language === \'fa\' ? \'یخچال\' : \'Nevera\'}: <b>{drinkSelected.fridge_stock} {drinkSelected.unit}</b></span><span>{language === \'fa\' ? \'بیرون\' : \'Fuera\'}: <b>{drinkSelected.outside_stock} {drinkSelected.unit}</b></span><span>{language === \'fa\' ? \'کل\' : \'Total\'}: <b>{drinkSelected.stock_quantity} {drinkSelected.unit}</b></span></div>}\n          <input required type="number" min="1" step="1" placeholder={language === \'fa\' ? \'تعداد انتقال به یخچال\' : \'Cantidad a pasar a nevera\'} value={drinkForm.transfer_quantity} onChange={e=>setDrinkForm({...drinkForm,transfer_quantity:e.target.value})}/>\n          <textarea placeholder={tr.notes} value={drinkForm.notes} onChange={e=>setDrinkForm({...drinkForm,notes:e.target.value})}/>\n          <button className="pay">{language === \'fa\' ? \'انتقال به یخچال\' : \'Trasladar a nevera\'}</button>\n        </form>\n      </div>\n      <div className="admin-table-wrap"><table className="admin-table beverage-table"><thead><tr><th>{language === \'fa\' ? \'نوشیدنی\' : \'Bebida\'}</th><th>{language === \'fa\' ? \'کل\' : \'Total\'}</th><th>{language === \'fa\' ? \'یخچال\' : \'Nevera\'}</th><th>{language === \'fa\' ? \'بیرون یخچال\' : \'Fuera\'}</th><th>{language === \'fa\' ? \'هشدارها\' : \'Alertas\'}</th></tr></thead><tbody>{drinks.map(item=><tr key={item.id}><td><b>{item.name}</b></td><td>{item.stock_quantity} {item.unit}</td><td className={item.fridge_stock <= item.fridge_alert_level ? \'stock-danger\' : \'\'}>{item.fridge_stock} {item.unit}</td><td>{item.outside_stock} {item.unit}</td><td>{item.fridge_stock <= item.fridge_alert_level && <span className="inventory-status urgent">{language === \'fa\' ? \'یخچال ≤ \' : \'Nevera ≤ \'}{item.fridge_alert_level}</span>} {item.stock_quantity < item.total_alert_level && <span className="inventory-status urgent">{language === \'fa\' ? \'کل < \' : \'Total < \'}{item.total_alert_level}</span>}</td></tr>)}{!drinks.length && <tr><td colSpan="5" className="muted">{language === \'fa\' ? \'هنوز نوشیدنی تعریف نشده است. یک ماده اولیه با واحد «unidad» بسازید و در فرم بالا آن را نوشیدنی کنید.\' : \'Todavía no hay bebidas. Crea un ingrediente con unidad “unidad” y configúralo arriba como bebida.\'}</td></tr>}</tbody></table></div>\n    </section>\n\n    <section className="admin-card"><h2>{tr.movements}</h2><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>{tr.ingredient}</th><th>{tr.type}</th><th>{tr.delta}</th><th>€</th><th>Fecha</th><th>{tr.notes}</th></tr></thead><tbody>{(data.recent_movements||[]).map(row=><tr key={row.id}><td>{row.ingredient_name}</td><td>{row.movement_type}</td><td>{row.quantity_delta} {row.unit}</td><td>{money(row.total_cost)}</td><td>{row.occurred_at ? new Date(row.occurred_at).toLocaleString() : \'\'}</td><td>{row.notes||row.reference}</td></tr>)}</tbody></table></div></section>\n  </section>;\n}\n\n\n'

CSS = """
/* v42 beverage fridge inventory */
.beverage-inventory-panel{display:grid;gap:15px}
.beverage-panel-head h2{margin:4px 0}.beverage-panel-head p{margin:0;color:#65544b}
.beverage-alerts{display:grid;gap:8px}.beverage-alert{padding:11px 13px;border-radius:10px;font-weight:700}
.beverage-alert.fridge_low{background:#fff2d9;color:#805000;border:1px solid #f1ca7a}
.beverage-alert.total_low{background:#fde8e6;color:#981d16;border:1px solid #efaaa5}
.beverage-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}
.beverage-form{border:1px solid #eadfd6;border-radius:13px;padding:14px;background:#fffcfa}
.beverage-form h3{margin:0 0 10px;font-size:16px}
.beverage-location-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;background:#f4f7ff;padding:10px;border-radius:10px;font-size:13px}
.beverage-location-summary span{display:grid;gap:3px}.stock-danger{color:#a1281d;font-weight:900}
.beverage-table .inventory-status{margin:2px}@media(max-width:760px){.beverage-grid{grid-template-columns:1fr}.beverage-location-summary{grid-template-columns:1fr}}
"""

def backup(path):
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    dest = path.with_name(f"{path.stem}_before_beverage_fridge_{stamp}{path.suffix}")
    shutil.copy2(path, dest)
    return dest

def replace_region(text, start_marker, end_marker, replacement, label):
    start = text.find(start_marker)
    end = text.find(end_marker, start)
    if start < 0 or end < 0:
        raise RuntimeError(f"Could not find {label}.")
    return text[:start] + replacement + text[end:]

def main():
    for file in (MODELS, VIEWS, MAIN, STYLES):
        if not file.exists():
            raise FileNotFoundError(f"Missing file: {file}")
    backups = {file: backup(file) for file in (MODELS, VIEWS, MAIN, STYLES)}
    try:
        models = MODELS.read_text(encoding="utf-8")
        if "is_beverage = models.BooleanField" not in models:
            anchor = "    supplier_name = models.CharField(max_length=160, blank=True, default='')"
            extra = anchor + """\n    # Beverage stock is split into fridge and outside-fridge locations.\n    is_beverage = models.BooleanField(default=False, db_index=True)\n    fridge_stock = models.DecimalField(max_digits=12, decimal_places=2, default=Decimal('0.00'))\n    fridge_alert_level = models.DecimalField(max_digits=12, decimal_places=2, default=Decimal('2.00'))\n    total_alert_level = models.DecimalField(max_digits=12, decimal_places=2, default=Decimal('8.00'))"""
            if anchor not in models:
                raise RuntimeError("Could not find Ingredient supplier_name field.")
            models = models.replace(anchor, extra, 1)
        if "TYPE_FRIDGE_TRANSFER = 'fridge_transfer'" not in models:
            models = models.replace(
                "    TYPE_ADJUSTMENT = 'adjustment'\n",
                "    TYPE_ADJUSTMENT = 'adjustment'\n    TYPE_FRIDGE_TRANSFER = 'fridge_transfer'\n", 1
            )
            models = models.replace(
                "        (TYPE_ADJUSTMENT, 'Ajuste manual'),\n",
                "        (TYPE_ADJUSTMENT, 'Ajuste manual'),\n        (TYPE_FRIDGE_TRANSFER, 'Traslado al frigorífico'),\n", 1
            )
        MODELS.write_text(models, encoding="utf-8")

        views = VIEWS.read_text(encoding="utf-8")
        views = replace_region(views, "def consume_inventory_for_order(order):", "\n\n@api_view(['GET'])\n@admin_token_required\ndef admin_inventory_real_overview", CONSUME, "consume_inventory_for_order")
        views = replace_region(views, "def admin_inventory_real_overview(request):", "\n\n@api_view(['POST'])\n@admin_token_required\ndef admin_inventory_purchase", OVERVIEW, "admin_inventory_real_overview")
        views = replace_region(views, "def admin_inventory_adjustment(request):", "\n\n# ============================================================\n# v23", ADJUSTMENT, "admin_inventory_adjustment")
        VIEWS.write_text(views, encoding="utf-8")

        main_text = MAIN.read_text(encoding="utf-8")
        main_text = replace_region(main_text, "function RealInventoryPanel({ expenseCategories = [] }) {", "\nfunction ProfitIntelligencePanel", PANEL, "RealInventoryPanel")
        MAIN.write_text(main_text, encoding="utf-8")

        css = STYLES.read_text(encoding="utf-8")
        if "v42 beverage fridge inventory" not in css:
            STYLES.write_text(css.rstrip() + "\n\n" + CSS + "\n", encoding="utf-8")
    except Exception:
        for original, saved in backups.items():
            shutil.copy2(saved, original)
        raise

    print("SUCCESS: Beverage fridge inventory installed.")
    print("Next: cd backend && python manage.py makemigrations restaurant --name beverage_fridge_inventory && python manage.py migrate && python manage.py check")

if __name__ == "__main__":
    main()
